def generar(idioma):
    texto = (AQUI / "zoom.es.html").read_text(encoding="utf-8")
    faltan = []
    for viejo, nuevo in comunes(idioma) + TEXTOS[idioma]:
        if viejo not in texto:
            faltan.append(viejo)
        texto = texto.replace(viejo, nuevo)
    if faltan:
        raise SystemExit(f"{idioma}: textos que ya no están en zoom.es.html:\n  " + "\n  ".join(f[:90] for f in faltan))
    destino = AQUI / f"zoom.{idioma}.html"
    destino.write_text(texto, encoding="utf-8")
    print(destino.name)


if __name__ == "__main__":
    for idioma in sys.argv[1:] or list(TEXTOS):
        generar(idioma)
